def render(prefix,lang):
 c=COPY[lang];money=lambda x:'RM'+format(x,',');text=lambda v:E(T(v,lang));link=lambda typ:prefix+'?service='+typ+'#project-brief'
 out='<nav aria-label="Breadcrumb"><ol class="service-crumbs"><li><a href="'+prefix+'">'+text(('Home','首页','Utama'))+'</a></li><li>'+c['label']+'</li></ol></nav>'
 out+='<section class="pricing-hero"><div><span class="service-eyebrow">KENNY STUDIO / '+c['label'].upper()+'</span><h1>'+c['h1']+'</h1><p class="service-lead">'+c['intro']+'</p><div class="service-actions"><a class="service-button" href="#website-packages">'+c['web']+' ↓</a><a class="service-text-link" href="'+prefix+'media/kenny-studio-pricing-en-zh.pdf" download>'+c['download']+' ↓</a></div><div class="pricing-assurances">'+''.join('<span>'+c[k]+'</span>' for k in ['single','revisions','support'])+'</div></div><div class="pricing-portrait"><video data-pricing-video muted loop playsinline preload="metadata" poster="'+prefix+'media/work-first.webp" aria-label="'+c['video']+'"><source src="'+prefix+'media/work-web.mp4" type="video/mp4"></video><div class="pricing-start"><small>'+c['from']+'</small><strong>RM1,000</strong><span>'+c['once']+'</span></div><button type="button" data-pricing-toggle aria-pressed="false" data-pause="'+c['pause']+'" data-play="'+c['play']+'">'+c['pause']+'</button></div></section>'
 sections=[('website-packages','web'),('monthly-care','care'),('add-ons','addons'),('search-marketing','search'),('scope-terms','terms')]
 out+='<nav class="pricing-jump" aria-label="'+c['jump']+'">'+''.join('<a href="#'+a+'">'+c[b]+'</a>' for a,b in sections)+'</nav>'
 out+='<section class="service-section" id="website-packages"><span class="service-eyebrow">01 / '+c['web'].upper()+'</span><h2>'+c['webTitle']+'</h2><p>'+c['webIntro']+'</p><div class="pricing-packages">'
 for i,p in enumerate(PLANS):
  out+='<article class="pricing-plan '+('pricing-featured' if p['id']=='signature' else '')+'"><div class="pricing-plan-top"><span class="service-eyebrow">0'+str(i+1)+'</span>'+('<span class="pricing-tag">'+c['selected']+'</span>' if p['id']=='signature' else '')+'</div><h3>'+text(p['name'])+'</h3><div class="pricing-amount"><span>'+c['from']+'</span><strong>'+money(p['price'])+'</strong><small>'+c['once']+'</small></div><ul>'+''.join('<li>'+text(v)+'</li>' for v in p['items'])+'</ul><a class="service-button" href="'+prefix+'cart/?add='+p['id']+'">'+text(('Add to basket','加入购物篮','Tambah ke troli'))+' ↗</a></article>'
 out+='</div></section><section class="service-section" id="monthly-care"><span class="service-eyebrow">02 / '+c['care'].upper()+'</span><h2>'+c['careTitle']+'</h2><p>'+c['careIntro']+'</p><div class="pricing-care">'
 for i,(name,price,items) in enumerate(CARE):
  out+='<article class="pricing-plan"><span class="service-eyebrow">0'+str(i+1)+'</span><h3>'+name+'</h3><div class="pricing-amount">'+('<span>'+c['from']+'</span>' if i==2 else '')+'<strong>'+money(price)+'</strong><small>'+c['month']+'</small></div><ul>'+''.join('<li>'+text(v)+'</li>' for v in items)+'</ul><a class="service-text-link" href="'+prefix+'cart/?add=care-'+str(i)+'">'+c['choose']+' ↗</a></article>'
 out+='</div><aside class="service-note">'+text(TERMS[6])+'</aside></section><section class="service-section" id="add-ons"><span class="service-eyebrow">03 / '+c['addons'].upper()+'</span><h2>'+c['addonTitle']+'</h2><p>'+c['addonIntro']+'</p><div class="pricing-table-wrap"><table class="pricing-table"><caption class="sr-only">'+c['addons']+'</caption><thead><tr>'+''.join('<th scope="col">'+c[k]+'</th>' for k in ['service','price','scope'])+'</tr></thead><tbody>'
 for addon_index,(name,price,unit,scope,starting) in enumerate(ADDONS):
  out+='<tr><th scope="row">'+text(name)+'<br><a class="service-text-link" href="'+prefix+'cart/?add=addon-'+str(addon_index)+'">'+text(('Add to basket','加入购物篮','Tambah ke troli'))+' +</a></th><td>'+('<small>'+c['from']+'</small>' if starting else '')+'<strong>'+money(price)+'</strong><span>'+text(unit)+'</span></td><td>'+text(scope)+'</td></tr>'
 out+='</tbody></table></div></section><section class="service-section" id="search-marketing"><span class="service-eyebrow">04 / '+c['search'].upper()+'</span><h2>'+c['searchTitle']+'</h2><p>'+c['searchIntro']+'</p><div class="pricing-search">'
 for search_index,(name,price,starting,unit,scope,form) in enumerate(SEARCH):
  out+='<article class="pricing-search-row"><div><h3>'+text(name)+'</h3><a class="service-text-link" href="'+prefix+'services/'+('seo/' if form=='seo' else 'google-ads-management/')+'">'+text(('Explore service','了解服务','Terokai perkhidmatan'))+' ↗</a></div><div class="pricing-amount">'+('<span>'+c['from']+'</span>' if starting else '')+'<strong>'+money(price)+'</strong><small>'+text(unit)+'</small></div><div><p>'+text(scope)+'</p><a href="'+prefix+'cart/?add=search-'+str(search_index)+'" class="service-text-link">'+c['choose']+' ↗</a></div></article>'
 out+='</div><aside class="service-note">'+text(TERMS[8])+'</aside></section><section class="service-section" id="scope-terms"><span class="service-eyebrow">05 / '+c['terms'].upper()+'</span><h2>'+c['termTitle']+'</h2><h3>'+c['payment']+'</h3><ol class="pricing-payments">'+''.join('<li><strong>'+pct+'</strong><span>'+E(label)+'</span></li>' for pct,label in zip(['50%','30%','20%'],c['paymentSteps']))+'</ol><div class="pricing-terms">'+''.join('<p>'+text(t)+'</p>' for t in TERMS)+'</div></section><section class="service-section"><div class="service-contact"><span class="service-eyebrow">KENNY STUDIO / MALAYSIA</span><h2>'+c['next']+'</h2><p>'+c['nextBody']+'</p><div class="service-actions"><a class="service-button" href="'+prefix+'#project-brief">'+c['cta']+' ↗</a><a class="service-text-link" href="'+prefix+'media/kenny-studio-pricing-en-zh.pdf" download>'+c['download']+' ↓</a></div><small>'+c['footerNote']+'</small></div></section>'
 return out
